#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>

int main() {
    int n, b;
    std::cin >> n >> b;
    std::vector<int> arr1(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> arr1[i];
    }

    std::vector<int> pf1(n, 0), pf2(n, 0);
    int sumOdd = 0, sumEven = 0;
    for (int i = 0; i < n; ++i) {
        if (arr1[i] % 2 == 0) sumEven++;
        else sumOdd++;
        pf1[i] = sumEven;
        pf2[i] = sumOdd;
    }

    std::vector<int> differences;
    int prev = 0;
    for (int i = 1; i < n - 2; i += 2) {
        int x, y;
        if (prev == 0) {
            x = pf1[i];
            y = pf2[i];
        } else {
            x = pf1[i] - pf1[prev];
            y = pf2[i] - pf2[prev];
        }
        if (x == y) {
            differences.push_back(std::abs(arr1[i + 1] - arr1[i]));
            prev = i;
        }
    }

    int p = differences.size();
    std::vector<int> arr(p);
    for (int i = 0; i < p; ++i) {
        arr[i] = differences[i];
    }

    std::vector<int> val(p, 1);
    std::vector<std::vector<int>> K(p + 1, std::vector<int>(b + 1, 0));

    for (int i = 1; i <= p; ++i) {
        for (int w = 0; w <= b; ++w) {
            if (arr[i - 1] <= w) {
                K[i][w] = std::max(val[i - 1] + K[i - 1][w - arr[i - 1]], K[i - 1][w]);
            } else {
                K[i][w] = K[i - 1][w];
            }
        }
    }

    std::cout << K[p][b] << std::endl;
    return 0;
}

